@app.post("/api/v1/debug/datadog-test-metrics", tags=["Debug"])
async def test_datadog_metrics(current_user: User = Depends(get_current_user)):
    """
    Send test metrics to DataDog.

    Useful for verifying the DataDog agent connection and metrics pipeline.
    """
    try:
        from datadog_monitoring import metrics, business_metrics

        # Send test metrics
        metrics.increment("test.counter", tags=["source:api_test"])
        metrics.gauge("test.gauge", 42.0, tags=["source:api_test"])
        metrics.histogram("test.histogram", 100.5, tags=["source:api_test"])

        # Send test business metric
        business_metrics.metrics.event(
            title="DataDog Test Event",
            text=f"Test event triggered by user {current_user.email}",
            alert_type="info",
            tags=["source:api_test", f"user:{current_user.id}"]
        )

        return {
            "success": True,
            "message": "Test metrics sent to DataDog",
            "metrics_sent": ["test.counter", "test.gauge", "test.histogram"],
            "event_sent": True
        }
    except ImportError:
        return {"success": False, "error": "DataDog monitoring module not available"}
    except Exception as e:
        return {"success": False, "error": str(e)}


@app.get("/api/v1/debug/cdn-status", tags=["Debug"])
async def get_cdn_status():
    """
    Get CloudFront CDN status and configuration.

    Returns information about CDN setup, distribution status,
    and whether CDN URLs are being used.
    """
    try:
        from services.cdn_service import get_cdn_service
        cdn = get_cdn_service()
        status = cdn.get_distribution_status()
        return {
            "cdn_enabled": cdn.enabled,
            "distribution_id": cdn.distribution_id,
            "domain_name": cdn.domain_name,
            "s3_bucket": cdn.s3_bucket,
            "signed_urls_available": bool(cdn._private_key and cdn.key_pair_id),
            "distribution_status": status
        }
    except ImportError:
        return {
            "cdn_enabled": False,
            "error": "CDN service module not available",
            "message": "Install cdn_service.py and configure CloudFront"
        }
    except Exception as e:
        return {
            "cdn_enabled": False,
            "error": str(e),
            "message": f"Error checking CDN status: {str(e)}"
        }


@app.post("/api/v1/debug/cdn-invalidate", tags=["Debug"])
async def invalidate_cdn_cache(
    paths: List[str] = Body(..., description="List of paths to invalidate"),
    current_user: User = Depends(get_current_user)
):
    """
    Invalidate CloudFront cache for specified paths.

    Requires admin or appropriate permissions.
    """
    try:
        from services.cdn_service import get_cdn_service
        cdn = get_cdn_service()

        if not cdn.enabled:
            return {"success": False, "error": "CDN not configured"}

        result = cdn.invalidate_cache(paths)
        return result
    except ImportError:
        return {"success": False, "error": "CDN service module not available"}
    except Exception as e:
        return {"success": False, "error": str(e)}


@app.post("/api/v1/debug/add-missing-roles", tags=["Debug"])
async def add_missing_employee_roles(
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    """
    Add missing employee roles to the onboarding_roles table.

    Adds: Admin, Site Admin, Executive Management, Management, Operations Manager,
          Branch Manager, Underwriter, Closer, Funder
    """
    if current_user.role != 'admin' and current_user.permission_role != 'admin':
        raise HTTPException(status_code=403, detail="Admin access required")

    try:
        from sqlalchemy import text as sql_text
        from datetime import datetime, timezone

        MISSING_ROLES = [
            {"name": "Admin", "description": "System administrator with full access"},
            {"name": "Site Admin", "description": "Site-level administrator"},
            {"name": "Executive Management", "description": "Executive management team"},
            {"name": "Management", "description": "Management role"},
            {"name": "Operations Manager", "description": "Operations manager overseeing daily operations"},
            {"name": "Branch Manager", "description": "Branch manager overseeing branch operations"},
            {"name": "Underwriter", "description": "Loan underwriter"},
            {"name": "Closer", "description": "Loan closer handling closing process"},
            {"name": "Funder", "description": "Loan funder handling funding process"},
        ]

        added = []
        skipped = []

        for role in MISSING_ROLES:
            # Check if role exists
            existing = db.execute(
                sql_text("SELECT id FROM onboarding_roles WHERE name = :name"),
                {"name": role["name"]}
            ).fetchone()

            if existing:
                skipped.append(role["name"])
            else:
                db.execute(
                    sql_text("""
                        INSERT INTO onboarding_roles (name, description, is_active, created_at, updated_at)
                        VALUES (:name, :description, true, :now, :now)
                    """),
                    {
                        "name": role["name"],
                        "description": role["description"],
                        "now": datetime.now(timezone.utc)
                    }
                )
                added.append(role["name"])

        db.commit()

        # Get all roles for display
        all_roles = db.execute(
            sql_text("SELECT id, name, is_active FROM onboarding_roles WHERE is_active = true ORDER BY name")
        ).fetchall()

        return {
            "success": True,
            "added": added,
            "skipped": skipped,
            "message": f"Added {len(added)} roles, skipped {len(skipped)} existing roles",
            "all_roles": [{"id": r[0], "name": r[1]} for r in all_roles]
        }

    except Exception as e:
        db.rollback()
        return {"success": False, "error": str(e)}


# PURL System Migration Endpoint
@app.post("/api/v1/migrations/add-purl-system")
async def add_purl_system_migration(db: Session = Depends(get_db)):
    """Run migration to add PURL (Persistent URL) borrower portal tables"""
    try:
        from sqlalchemy import text as sql_text

        sql_commands = [
            "CREATE EXTENSION IF NOT EXISTS pgcrypto",
            "CREATE EXTENSION IF NOT EXISTS citext",
            """CREATE TABLE IF NOT EXISTS purl_workspaces (
                id SERIAL PRIMARY KEY,
                organization_id INTEGER REFERENCES organizations(id) ON DELETE CASCADE,
                slug VARCHAR(255) NOT NULL,
                status VARCHAR(50) NOT NULL DEFAULT 'lead',
                display_name VARCHAR(500) NOT NULL,
                source VARCHAR(255),
                owner_user_id INTEGER REFERENCES users(id),
                lead_at TIMESTAMP WITH TIME ZONE,
                application_at TIMESTAMP WITH TIME ZONE,
                active_loan_at TIMESTAMP WITH TIME ZONE,
                closing_at TIMESTAMP WITH TIME ZONE,
                post_close_at TIMESTAMP WITH TIME ZONE,
                meta_data JSONB NOT NULL DEFAULT '{}'::jsonb,
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(organization_id, slug)
            )""",
            "CREATE INDEX IF NOT EXISTS idx_purl_workspaces_org_status ON purl_workspaces(organization_id, status)",
            "CREATE INDEX IF NOT EXISTS idx_purl_workspaces_slug ON purl_workspaces(slug)",
            """CREATE TABLE IF NOT EXISTS purl_contacts (
                id SERIAL PRIMARY KEY,
                organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
                workspace_id INTEGER NOT NULL REFERENCES purl_workspaces(id) ON DELETE CASCADE,
                contact_type VARCHAR(50) NOT NULL,
                first_name VARCHAR(255) NOT NULL,
                last_name VARCHAR(255) NOT NULL,
                email VARCHAR(255),
                phone VARCHAR(50),
                auth_user_id INTEGER REFERENCES users(id),
                meta_data JSONB NOT NULL DEFAULT '{}'::jsonb,
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
            )""",
            "CREATE INDEX IF NOT EXISTS idx_purl_contacts_workspace ON purl_contacts(workspace_id)",
            """CREATE TABLE IF NOT EXISTS purl_access_tokens (
                id SERIAL PRIMARY KEY,
                organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
                workspace_id INTEGER NOT NULL REFERENCES purl_workspaces(id) ON DELETE CASCADE,
                contact_id INTEGER REFERENCES purl_contacts(id) ON DELETE CASCADE,
                token_hash VARCHAR(64) NOT NULL UNIQUE,
                scope VARCHAR(20) NOT NULL DEFAULT 'read',
                expires_at TIMESTAMP WITH TIME ZONE,
                last_used_at TIMESTAMP WITH TIME ZONE,
                revoked_at TIMESTAMP WITH TIME ZONE,
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
            )""",
            "CREATE INDEX IF NOT EXISTS idx_purl_tokens_hash ON purl_access_tokens(token_hash)",
            """CREATE TABLE IF NOT EXISTS purl_applications (
                id SERIAL PRIMARY KEY,
                organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
                workspace_id INTEGER NOT NULL REFERENCES purl_workspaces(id) ON DELETE CASCADE,
                application_type VARCHAR(20) NOT NULL,
                status VARCHAR(30) NOT NULL DEFAULT 'in_progress',
                version INTEGER NOT NULL DEFAULT 1,
                data JSONB NOT NULL DEFAULT '{}'::jsonb,
                completeness_pct INTEGER DEFAULT 0,
                started_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
                submitted_at TIMESTAMP WITH TIME ZONE,
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                UNIQUE(workspace_id, application_type, version)
            )""",
            """CREATE TABLE IF NOT EXISTS purl_loans (
                id SERIAL PRIMARY KEY,
                organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
                workspace_id INTEGER NOT NULL REFERENCES purl_workspaces(id) ON DELETE CASCADE,
                application_id INTEGER REFERENCES purl_applications(id),
                main_loan_id INTEGER,
                loan_number VARCHAR(100),
                status VARCHAR(30) NOT NULL DEFAULT 'active',
                loan_purpose VARCHAR(50),
                loan_amount DECIMAL(15, 2),
                meta_data JSONB NOT NULL DEFAULT '{}'::jsonb,
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
            )""",
            """CREATE TABLE IF NOT EXISTS purl_documents (
                id SERIAL PRIMARY KEY,
                organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
                workspace_id INTEGER NOT NULL REFERENCES purl_workspaces(id) ON DELETE CASCADE,
                loan_id INTEGER REFERENCES purl_loans(id) ON DELETE CASCADE,
                doc_type VARCHAR(100) NOT NULL,
                doc_category VARCHAR(50) NOT NULL,
                status VARCHAR(30) NOT NULL DEFAULT 'uploaded',
                file_name VARCHAR(500) NOT NULL,
                storage_key VARCHAR(1000) NOT NULL UNIQUE,
                size_bytes BIGINT NOT NULL,
                mime_type VARCHAR(255) NOT NULL,
                uploaded_by_contact_id INTEGER REFERENCES purl_contacts(id),
                uploaded_by_user_id INTEGER REFERENCES users(id),
                meta_data JSONB NOT NULL DEFAULT '{}'::jsonb,
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
            )""",
            """CREATE TABLE IF NOT EXISTS purl_tasks (
                id SERIAL PRIMARY KEY,
                organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
                workspace_id INTEGER REFERENCES purl_workspaces(id) ON DELETE CASCADE,
                title VARCHAR(500) NOT NULL,
                description TEXT,
                task_type VARCHAR(50) DEFAULT 'general',
                status VARCHAR(30) NOT NULL DEFAULT 'open',
                priority VARCHAR(20) NOT NULL DEFAULT 'medium',
                assigned_to_user_id INTEGER REFERENCES users(id),
                assigned_to_contact_id INTEGER REFERENCES purl_contacts(id),
                due_at TIMESTAMP WITH TIME ZONE,
                completed_at TIMESTAMP WITH TIME ZONE,
                meta_data JSONB NOT NULL DEFAULT '{}'::jsonb,
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
            )""",
            """CREATE TABLE IF NOT EXISTS purl_messages (
                id SERIAL PRIMARY KEY,
                organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
                workspace_id INTEGER NOT NULL REFERENCES purl_workspaces(id) ON DELETE CASCADE,
                message_type VARCHAR(30) NOT NULL DEFAULT 'text',
                content TEXT NOT NULL,
                sender_type VARCHAR(20) NOT NULL,
                sender_user_id INTEGER REFERENCES users(id),
                sender_contact_id INTEGER REFERENCES purl_contacts(id),
                related_document_id INTEGER REFERENCES purl_documents(id),
                related_task_id INTEGER REFERENCES purl_tasks(id),
                is_read_by_borrower BOOLEAN DEFAULT FALSE,
                read_at TIMESTAMP WITH TIME ZONE,
                meta_data JSONB NOT NULL DEFAULT '{}'::jsonb,
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
            )""",
            "CREATE INDEX IF NOT EXISTS idx_purl_messages_workspace ON purl_messages(workspace_id, created_at DESC)",
            """CREATE TABLE IF NOT EXISTS purl_audit_log (
                id SERIAL PRIMARY KEY,
                organization_id INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
                actor_type VARCHAR(20) NOT NULL,
                actor_id INTEGER,
                workspace_id INTEGER REFERENCES purl_workspaces(id),
                action VARCHAR(100) NOT NULL,
                resource_type VARCHAR(100) NOT NULL,
                resource_id INTEGER,
                changes JSONB,
                meta_data JSONB NOT NULL DEFAULT '{}'::jsonb,
                ip_address VARCHAR(45),
                request_id VARCHAR(100),
                created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
            )""",
            "CREATE INDEX IF NOT EXISTS idx_purl_audit_workspace ON purl_audit_log(workspace_id, created_at DESC)"
        ]

        success_count = 0
        errors = []
        for i, sql in enumerate(sql_commands):
            try:
                db.execute(sql_text(sql))
                db.commit()
                success_count += 1
            except Exception as e:
                db.rollback()
                error_msg = str(e)
                if 'already exists' in error_msg.lower() or 'duplicate' in error_msg.lower():
                    success_count += 1
                    continue
                errors.append(f"Statement {i+1}: {error_msg[:200]}")

        return {
            "success": len(errors) == 0,
            "message": f"PURL migration: {success_count}/{len(sql_commands)} statements succeeded",
            "tables_created": [
                "purl_workspaces", "purl_contacts", "purl_access_tokens",
                "purl_applications", "purl_loans", "purl_documents",
                "purl_tasks", "purl_messages", "purl_audit_log"
            ],
            "errors": errors if errors else None
        }
    except Exception as e:
        return {"success": False, "error": str(e)}


# Email Monitor Migration Endpoint
@app.post("/api/v1/migrations/add-email-monitor")
async def add_email_monitor_migration(db: Session = Depends(get_db)):
    """Run migration to add email monitor tables"""
    try:
        import os
        from sqlalchemy import text as sql_text

        migration_path = os.path.join(os.path.dirname(__file__), "migrations", "add_email_monitor_tables.sql")

        with open(migration_path, 'r') as f:
            sql = f.read()

        # Split by semicolon and filter
        raw_statements = sql.split(';')
        statements = []
        for s in raw_statements:
            # Strip leading comment lines
            lines = s.strip().split('\n')
            clean_lines = [l for l in lines if not l.strip().startswith('--')]
            clean_stmt = '\n'.join(clean_lines).strip()
            if clean_stmt:
                statements.append(clean_stmt)

        results = []
        success_count = 0
        for i, statement in enumerate(statements):
            try:
                db.execute(sql_text(statement))
                db.commit()
                success_count += 1
            except Exception as e:
                db.rollback()
                error_msg = str(e)
                if 'already exists' in error_msg.lower() or 'duplicate' in error_msg.lower():
                    success_count += 1
                    continue
                results.append(f"Statement {i+1}: {error_msg[:200]}")

        return {
            "success": len(results) == 0,
            "message": f"Email monitor migration: {success_count} statements succeeded",
            "tables_created": [
                "email_monitor_addresses", "email_monitor_keywords", "email_monitor_rules",
                "email_monitor_captured", "email_crm_links", "email_relevance_analysis",
                "email_filter_whitelist", "email_filter_blacklist", "email_provider_config",
                "gmail_oauth_tokens", "outlook_oauth_tokens", "email_monitor_log"
            ],
            "total_statements": len(statements),
            "succeeded": success_count,
            "errors": results if results else None
        }
    except Exception as e:
        return {"success": False, "error": str(e)}

