@app.get("/api/v1/admin/security/dashboard")
async def get_security_dashboard(current_user: User = Depends(get_current_user)):
    """
    Get security dashboard metrics including blocked IPs, rate limits, and failed logins.
    Requires admin or management role.
    """
    if current_user.role not in ['admin', 'management']:
        raise HTTPException(status_code=403, detail="Admin access required")

    return security_stats.get_dashboard_data()

@app.post("/api/v1/admin/security/unblock-ip/{ip}")
async def unblock_ip_address(ip: str, current_user: User = Depends(get_current_user)):
    """
    Unblock a blocked IP address.
    Requires admin or management role.
    """
    if current_user.role not in ['admin', 'management']:
        raise HTTPException(status_code=403, detail="Admin access required")

    if security_stats.unblock_ip(ip):
        logger.info(f"IP {ip} unblocked by {current_user.email}")
        return {"message": f"IP {ip} has been unblocked", "success": True}
    else:
        return {"message": f"IP {ip} was not blocked", "success": False}

@app.get("/api/v1/users/me")
async def get_current_user_info(current_user: User = Depends(get_current_user)):
    """Get current user information including onboarding status"""
    # Parse business_hours JSON if it exists
    business_hours = getattr(current_user, 'business_hours', None) or {}

    # Generate a slug from name if not set
    user_slug = getattr(current_user, 'slug', None)
    if not user_slug and current_user.full_name:
        # Create URL-friendly slug from name
        import re
        user_slug = re.sub(r'[^a-z0-9]+', '-', current_user.full_name.lower()).strip('-')

    return {
        "id": current_user.id,
        "email": current_user.email,
        "full_name": current_user.full_name,
        "role": current_user.role,
        "is_active": current_user.is_active,
        "email_verified": current_user.email_verified,
        "onboarding_completed": current_user.onboarding_completed,
        "user_metadata": current_user.user_metadata,
        "phone": getattr(current_user, 'phone', None),
        "nmls_number": getattr(current_user, 'nmls_number', None),
        "job_title": getattr(current_user, 'title', None),  # Map from 'title' column
        "slug": user_slug,
        "work_hours_start": business_hours.get('start', '09:00') if business_hours else '09:00',
        "work_hours_end": business_hours.get('end', '17:00') if business_hours else '17:00',
        "work_days": business_hours.get('days', ['monday', 'tuesday', 'wednesday', 'thursday', 'friday']) if business_hours else ['monday', 'tuesday', 'wednesday', 'thursday', 'friday'],
        "created_at": current_user.created_at.isoformat() if current_user.created_at else None
    }


class UserProfileUpdate(BaseModel):
    """Schema for updating user profile"""
    full_name: Optional[str] = None
    phone: Optional[str] = None
    nmls_number: Optional[str] = None
    job_title: Optional[str] = None
    work_hours_start: Optional[str] = None  # e.g., "09:00"
    work_hours_end: Optional[str] = None    # e.g., "17:00"
    work_days: Optional[List[str]] = None   # e.g., ["monday", "tuesday", ...]


@app.put("/api/v1/users/me")
async def update_current_user_profile(
    profile_update: UserProfileUpdate,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    """Update current user's profile information"""
    from sqlalchemy import text
    import json as json_module
    import traceback

    try:
        logger.info(f"Profile update request for user {current_user.id}: {profile_update.dict(exclude_none=True)}")

        # Use raw SQL to update to avoid SQLAlchemy model issues with missing columns
        update_fields = []
        params = {"user_id": current_user.id}

        if profile_update.full_name is not None:
            # Parse full_name into first_name and last_name (database has separate columns)
            name_parts = profile_update.full_name.strip().split(None, 1)  # Split on first whitespace
            first_name = name_parts[0] if name_parts else ""
            last_name = name_parts[1] if len(name_parts) > 1 else ""

            update_fields.append("first_name = :first_name")
            params["first_name"] = first_name
            update_fields.append("last_name = :last_name")
            params["last_name"] = last_name

        if profile_update.phone is not None:
            update_fields.append("phone = :phone")
            params["phone"] = profile_update.phone

        if profile_update.nmls_number is not None:
            update_fields.append("nmls_number = :nmls_number")
            params["nmls_number"] = profile_update.nmls_number

        if profile_update.job_title is not None:
            update_fields.append("title = :title")
            params["title"] = profile_update.job_title

        # Handle business hours
        if profile_update.work_hours_start is not None or profile_update.work_hours_end is not None or profile_update.work_days is not None:
            try:
                # Get current business hours
                result = db.execute(text("SELECT business_hours FROM users WHERE id = :user_id"), {"user_id": current_user.id}).fetchone()
                business_hours = {}
                if result and result[0]:
                    if isinstance(result[0], dict):
                        business_hours = dict(result[0])
                    elif isinstance(result[0], str):
                        business_hours = json_module.loads(result[0])

                if profile_update.work_hours_start is not None:
                    business_hours['start'] = profile_update.work_hours_start
                if profile_update.work_hours_end is not None:
                    business_hours['end'] = profile_update.work_hours_end
                if profile_update.work_days is not None:
                    business_hours['days'] = profile_update.work_days

                # Use CAST for PostgreSQL compatibility
                update_fields.append("business_hours = CAST(:business_hours AS json)")
                params["business_hours"] = json_module.dumps(business_hours)
            except Exception as bh_error:
                logger.warning(f"Could not update business_hours: {bh_error}")
                # Continue without business hours update

        if update_fields:
            sql = f"UPDATE users SET {', '.join(update_fields)} WHERE id = :user_id"
            logger.info(f"Executing SQL: {sql} with params: {params}")
            db.execute(text(sql), params)
            db.commit()
            logger.info(f"Profile SQL update successful for user {current_user.id}")

        # Fetch updated user data directly with SQL to avoid ORM issues
        user_result = db.execute(text("""
            SELECT id, email, first_name, last_name, phone, nmls_number, title, business_hours
            FROM users WHERE id = :user_id
        """), {"user_id": current_user.id}).fetchone()

        if not user_result:
            raise HTTPException(status_code=404, detail="User not found after update")

        # Compute full_name from first_name and last_name
        first_name = user_result[2] or ""
        last_name = user_result[3] or ""
        computed_full_name = f"{first_name} {last_name}".strip() if first_name or last_name else ""

        # Parse business hours from result
        business_hours = {}
        if user_result[7]:  # business_hours column (index shifted due to first_name/last_name split)
            if isinstance(user_result[7], dict):
                business_hours = user_result[7]
            elif isinstance(user_result[7], str):
                try:
                    business_hours = json_module.loads(user_result[7])
                except (json.JSONDecodeError, TypeError):
                    business_hours = {}

        logger.info(f"Profile updated successfully for user {current_user.email}")
        return {
            "success": True,
            "message": "Profile updated successfully",
            "user": {
                "id": user_result[0],
                "email": user_result[1],
                "full_name": computed_full_name,
                "first_name": first_name,
                "last_name": last_name,
                "phone": user_result[4],
                "nmls_number": user_result[5],
                "job_title": user_result[6],  # title column
                "work_hours_start": business_hours.get('start', '09:00'),
                "work_hours_end": business_hours.get('end', '17:00'),
                "work_days": business_hours.get('days', ['monday', 'tuesday', 'wednesday', 'thursday', 'friday'])
            }
        }
    except HTTPException:
        raise
    except Exception as e:
        db.rollback()
        logger.error(f"Error updating profile for user {current_user.id}: {e}")
        logger.error(f"Full traceback: {traceback.format_exc()}")
        raise HTTPException(status_code=500, detail=f"Profile update failed: {str(e)}")


@app.post("/api/v1/users/{user_id}/photo")
async def upload_user_photo(
    user_id: int,
    photo: UploadFile = File(...),
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    """Upload a profile photo for a user (self or with admin permissions)"""
    import uuid
    import os

    try:
        # Check permissions - must be self or admin
        if current_user.id != user_id and not getattr(current_user, 'is_admin', False):
            raise HTTPException(status_code=403, detail="Not authorized to update this user's photo")

        # Validate file type
        allowed_types = ['image/jpeg', 'image/png', 'image/gif', 'image/webp']
        if photo.content_type not in allowed_types:
            raise HTTPException(status_code=400, detail="Invalid file type. Allowed: JPEG, PNG, GIF, WebP")

        # Validate file size (max 5MB)
        contents = await photo.read()
        if len(contents) > 5 * 1024 * 1024:
            raise HTTPException(status_code=400, detail="File too large. Maximum size is 5MB")

        # Generate unique filename
        ext = photo.filename.split('.')[-1] if '.' in photo.filename else 'jpg'
        filename = f"profile_{user_id}_{uuid.uuid4().hex[:8]}.{ext}"

        # Ensure upload directory exists
        upload_dir = os.path.join(os.path.dirname(__file__), 'uploads', 'profiles')
        os.makedirs(upload_dir, exist_ok=True)

        # Save file
        file_path = os.path.join(upload_dir, filename)
        with open(file_path, 'wb') as f:
            f.write(contents)

        # Update user's photo URL
        photo_url = f"/uploads/profiles/{filename}"
        target_user = db.query(User).filter(User.id == user_id).first()
        if target_user:
            if hasattr(target_user, 'photo_url'):
                target_user.photo_url = photo_url
            elif hasattr(target_user, 'profile_photo'):
                target_user.profile_photo = photo_url
            db.commit()

        logger.info(f"Photo uploaded for user {user_id}: {filename}")
        return {
            "success": True,
            "photo_url": photo_url,
            "message": "Photo uploaded successfully"
        }

    except HTTPException:
        raise
    except Exception as e:
        logger.error(f"Error uploading photo: {e}")
        raise HTTPException(status_code=500, detail=str(e))


class PasswordChange(BaseModel):
    """Schema for changing password"""
    current_password: str
    new_password: str


@app.put("/api/v1/users/me/password")
async def change_current_user_password(
    password_data: PasswordChange,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    """Change current user's password"""
    try:
        # Verify current password
        if not pwd_context.verify(password_data.current_password, current_user.hashed_password):
            raise HTTPException(status_code=400, detail="Current password is incorrect")

        # Validate new password
        if len(password_data.new_password) < 6:
            raise HTTPException(status_code=400, detail="New password must be at least 6 characters")

        # Hash and save new password
        current_user.hashed_password = pwd_context.hash(password_data.new_password)
        db.commit()

        logger.info(f"Password changed for user {current_user.email}")
        return {"success": True, "message": "Password changed successfully"}
    except HTTPException:
        raise
    except Exception as e:
        db.rollback()
        logger.error(f"Error changing password: {e}")
        raise HTTPException(status_code=500, detail=str(e))


@app.patch("/api/v1/users/me/goals")
async def update_user_goals(
    goals: dict,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    """Save user's production goals from Goal Tracker"""
    user_metadata = current_user.user_metadata or {}
    user_metadata['goals'] = goals

    current_user.user_metadata = user_metadata
    db.commit()
    db.refresh(current_user)

    logger.info(f"Goals updated for user {current_user.email}")
    return {"success": True, "goals": goals}


