@app.get("/api/v1/public/migrations/fix-tloss-account")
async def fix_tloss_account_migration(
    migration_key: str = "",
    db: Session = Depends(get_db)
):
    """Fix Tim Loss account - update SF integration user_id and reset password."""
    if migration_key != "fix-tloss":
        raise HTTPException(status_code=403, detail="Invalid migration key")

    result = {"steps": []}

    try:
        # Step 1: Update Salesforce integration user_id from 57 to 118
        sf_update = db.execute(text("""
            UPDATE user_integrations
            SET user_id = 118
            WHERE provider = 'salesforce' AND user_id = 57
        """))
        result["sf_integration_updated"] = sf_update.rowcount
        result["steps"].append(f"Updated {sf_update.rowcount} SF integration(s) to user_id 118")

        # Step 2: Reset password using raw SQL to ensure it works
        new_password = "Woodwindow00!"
        hashed = pwd_context.hash(new_password)
        pwd_update = db.execute(text("""
            UPDATE users
            SET hashed_password = :hashed
            WHERE email = 'tloss@cmgfi.com'
        """), {"hashed": hashed})
        result["password_updated"] = pwd_update.rowcount
        result["steps"].append(f"Updated password for {pwd_update.rowcount} user(s)")

        db.commit()

        # Step 3: Verify password works
        user = db.execute(text("""
            SELECT id, email, hashed_password FROM users WHERE email = 'tloss@cmgfi.com'
        """)).fetchone()

        if user and user[2]:
            verify_result = pwd_context.verify(new_password, user[2])
            result["password_verify"] = verify_result
            result["steps"].append(f"Password verification: {verify_result}")
        else:
            result["password_verify"] = False
            result["steps"].append("Could not verify - user or password not found")

        result["status"] = "success"
        return result
    except Exception as e:
        db.rollback()
        return {"status": "error", "error": str(e)}


@app.get("/api/v1/public/migrations/test-login")
async def test_login_migration(
    migration_key: str = "",
    email: str = "tloss@cmgfi.com",
    password: str = "Woodwindow00!",
    db: Session = Depends(get_db)
):
    """Debug login by comparing ORM vs raw SQL user retrieval."""
    if migration_key != "test-login":
        raise HTTPException(status_code=403, detail="Invalid migration key")

    result = {"steps": [], "comparisons": {}}

    try:
        # Method 1: ORM query (same as login endpoint)
        orm_user = db.query(User).filter(User.email == email).first()
        if orm_user:
            result["orm"] = {
                "found": True,
                "id": orm_user.id,
                "email": orm_user.email,
                "has_password": bool(orm_user.hashed_password),
                "password_length": len(orm_user.hashed_password) if orm_user.hashed_password else 0,
                "password_prefix": orm_user.hashed_password[:20] if orm_user.hashed_password else None,
                "verify_result": pwd_context.verify(password, orm_user.hashed_password) if orm_user.hashed_password else False,
            }
            result["steps"].append("ORM query found user")
        else:
            result["orm"] = {"found": False}
            result["steps"].append("ORM query: user NOT found")

        # Method 2: Raw SQL query (same as fix endpoint)
        raw_user = db.execute(text("""
            SELECT id, email, hashed_password FROM users WHERE email = :email
        """), {"email": email}).fetchone()

        if raw_user:
            result["raw_sql"] = {
                "found": True,
                "id": raw_user[0],
                "email": raw_user[1],
                "has_password": bool(raw_user[2]),
                "password_length": len(raw_user[2]) if raw_user[2] else 0,
                "password_prefix": raw_user[2][:20] if raw_user[2] else None,
                "verify_result": pwd_context.verify(password, raw_user[2]) if raw_user[2] else False,
            }
            result["steps"].append("Raw SQL found user")
        else:
            result["raw_sql"] = {"found": False}
            result["steps"].append("Raw SQL: user NOT found")

        # Compare the two
        if result.get("orm", {}).get("found") and result.get("raw_sql", {}).get("found"):
            result["comparisons"] = {
                "ids_match": result["orm"]["id"] == result["raw_sql"]["id"],
                "passwords_match": result["orm"]["password_prefix"] == result["raw_sql"]["password_prefix"],
                "orm_verify": result["orm"]["verify_result"],
                "raw_verify": result["raw_sql"]["verify_result"],
            }

        # Also check what verify_password function returns
        if orm_user and orm_user.hashed_password:
            result["verify_password_func"] = verify_password(password, orm_user.hashed_password)

        result["status"] = "success"
        return result
    except Exception as e:
        import traceback
        return {"status": "error", "error": str(e), "traceback": traceback.format_exc()}


@app.get("/api/v1/public/migrations/refresh-salesforce-token")
async def refresh_salesforce_token_migration(
    migration_key: str = "",
    db: Session = Depends(get_db)
):
    """Diagnostic endpoint to test and refresh Salesforce token."""
    if migration_key != "refresh-sf":
        raise HTTPException(status_code=403, detail="Invalid migration key")

    result = {"steps": []}

    try:
        # Step 1: Get tokens from database
        integration = db.execute(text("""
            SELECT user_id, access_token, refresh_token, scopes, email
            FROM user_integrations
            WHERE provider = 'salesforce'
            ORDER BY updated_at DESC
            LIMIT 1
        """)).fetchone()

        if not integration:
            return {"error": "No Salesforce integration found"}

        result["user_id"] = integration[0]
        result["sf_email"] = integration[4]
        result["steps"].append("Found integration")

        access_token = integration[1]
        refresh_token = integration[2]
        scopes = integration[3] or ""

        result["has_access_token"] = bool(access_token)
        result["has_refresh_token"] = bool(refresh_token)

        # Step 2: Try to decrypt tokens
        try:
            from routes.salesforce_routes import decrypt_token
            decrypted_access = decrypt_token(access_token)
            decrypted_refresh = decrypt_token(refresh_token)
            result["tokens_encrypted"] = decrypted_access != access_token
            result["steps"].append("Tokens decrypted")
            access_token = decrypted_access
            refresh_token = decrypted_refresh
        except Exception as e:
            result["decrypt_error"] = str(e)
            result["tokens_encrypted"] = False

        # Step 3: Parse instance URL
        instance_url = None
        if "instance_url:" in scopes:
            instance_url = scopes.split("instance_url:")[1].split(",")[0].strip()
        result["instance_url"] = instance_url
        result["steps"].append(f"Instance URL: {instance_url}")

        # Step 4: Try the current token
        if instance_url and access_token:
            import requests as req
            test_response = req.get(
                f"{instance_url}/services/oauth2/userinfo",
                headers={"Authorization": f"Bearer {access_token}"},
                timeout=30
            )
            result["current_token_status"] = test_response.status_code
            result["steps"].append(f"Current token test: {test_response.status_code}")

            if test_response.status_code == 200:
                result["status"] = "success"
                result["message"] = "Current token is valid"
                return result

        # Step 5: Try to refresh
        if refresh_token:
            try:
                from integrations.salesforce_service import salesforce_client
                new_tokens = salesforce_client.refresh_access_token(refresh_token)

                if new_tokens and new_tokens.get("access_token"):
                    new_access_token = new_tokens["access_token"]
                    result["refresh_success"] = True
                    result["new_token_length"] = len(new_access_token)
                    result["steps"].append("Token refreshed successfully")

                    # Calculate expiration (Salesforce tokens typically expire in 2 hours)
                    expires_in = new_tokens.get("expires_in", 7200)  # Default 2 hours
                    expires_at = datetime.now(timezone.utc) + timedelta(seconds=int(expires_in))

                    # Update in database with expires_at
                    db.execute(text("""
                        UPDATE user_integrations
                        SET access_token = :access_token,
                            expires_at = :expires_at,
                            updated_at = CURRENT_TIMESTAMP
                        WHERE user_id = :user_id AND provider = 'salesforce'
                    """), {
                        "access_token": new_access_token,
                        "expires_at": expires_at,
                        "user_id": integration[0]
                    })
                    db.commit()

                    result["status"] = "success"
                    result["message"] = "Token refreshed and saved"
                    result["expires_at"] = expires_at.isoformat()
                else:
                    result["refresh_success"] = False
                    result["status"] = "error"
                    result["message"] = "Refresh token has expired. User must reconnect Salesforce at Settings > Integrations by clicking 'Reconnect'."
                    result["action_required"] = "RECONNECT"
            except Exception as e:
                result["refresh_error"] = str(e)
                result["status"] = "error"
                result["message"] = f"Refresh failed: {str(e)}"
        else:
            result["status"] = "error"
            result["message"] = "No refresh token available"

        return result
    except Exception as e:
        return {"status": "error", "error": str(e)}


