@app.get("/api/v1/migrations/check-enum-values", response_model=None)
async def check_enum_values(
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    """
    Check what enum values exist in the PostgreSQL database.
    Useful for debugging enum mismatches.
    """
    try:
        # Get leadstage enum values
        result = db.execute(text("""
            SELECT enumlabel FROM pg_enum
            WHERE enumtypid = (SELECT oid FROM pg_type WHERE typname = 'leadstage')
            ORDER BY enumsortorder
        """))
        lead_stages = [row[0] for row in result.fetchall()]

        # Get loanstage enum values
        result = db.execute(text("""
            SELECT enumlabel FROM pg_enum
            WHERE enumtypid = (SELECT oid FROM pg_type WHERE typname = 'loanstage')
            ORDER BY enumsortorder
        """))
        loan_stages = [row[0] for row in result.fetchall()]

        # Get distinct values actually in leads table
        result = db.execute(text("SELECT DISTINCT stage::text FROM leads WHERE stage IS NOT NULL"))
        lead_data = [row[0] for row in result.fetchall()]

        # Get distinct values actually in loans table
        result = db.execute(text("SELECT DISTINCT stage::text FROM loans WHERE stage IS NOT NULL"))
        loan_data = [row[0] for row in result.fetchall()]

        return {
            "postgresql_leadstage_enum": lead_stages,
            "postgresql_loanstage_enum": loan_stages,
            "lead_data_values": lead_data,
            "loan_data_values": loan_data
        }

    except Exception as e:
        return {"error": str(e)}


@app.post("/api/v1/migrations/normalize-stage-enums", response_model=None)
async def normalize_stage_enums_migration(
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    """
    Migration: Normalize lead and loan stage enum values.

    Converts all stage values to use Python enum NAMES (like 'NEW', 'PRE_APPROVED')
    which is what SQLAlchemy's native PostgreSQL enum expects by default.

    This fixes the LookupError when SQLAlchemy tries to map database values
    back to Python enum members.
    """
    try:
        logger.info(f"Running migration: normalize stage enums (user: {current_user.id})")

        results = {"leads": {}, "loans": {}}

        # Get raw connection for direct SQL execution
        connection = engine.raw_connection()
        cursor = connection.cursor()

        try:
            # LeadStage: Map enum VALUES to NAMES (SQLAlchemy expects names)
            lead_stage_mappings = [
                ("New", "NEW"),
                ("Attempted Contact", "ATTEMPTED_CONTACT"),
                ("Prospect", "PROSPECT"),
                ("Application", "APPLICATION"),
                ("Pre-Qualified", "PRE_QUALIFIED"),
                ("Pre-Approved", "PRE_APPROVED"),
                ("Under Contract", "UNDER_CONTRACT"),
                ("Long-Term Nurture", "LONG_TERM_NURTURE"),
                ("Closed", "CLOSED"),
                ("Referral Source", "REFERRAL_SOURCE"),
                ("Withdrawn", "WITHDRAWN"),
                ("Does Not Qualify", "DOES_NOT_QUALIFY"),
                # Also handle legacy values
                ("APPLICATION_STARTED", "APPLICATION"),
                ("APPLICATION_COMPLETE", "APPLICATION"),
            ]

            for old_value, new_value in lead_stage_mappings:
                if old_value != new_value:
                    cursor.execute(
                        "UPDATE leads SET stage = %s WHERE stage = %s",
                        (new_value, old_value)
                    )
                    if cursor.rowcount > 0:
                        results["leads"][old_value] = cursor.rowcount
                        logger.info(f"Normalized {cursor.rowcount} leads: '{old_value}' -> '{new_value}'")

            # LoanStage: Map enum VALUES to NAMES (SQLAlchemy expects names)
            loan_stage_mappings = [
                ("Disclosed", "DISCLOSED"),
                ("Processing", "PROCESSING"),
                ("Submitted", "SUBMITTED"),
                ("UW Received", "UW_RECEIVED"),
                ("Approved", "APPROVED"),
                ("Suspended", "SUSPENDED"),
                ("Docs Out", "DOCS"),
                ("Funded", "FUNDED"),
            ]

            for old_value, new_value in loan_stage_mappings:
                if old_value != new_value:
                    cursor.execute(
                        "UPDATE loans SET stage = %s WHERE stage = %s",
                        (new_value, old_value)
                    )
                    if cursor.rowcount > 0:
                        results["loans"][old_value] = cursor.rowcount
                        logger.info(f"Normalized {cursor.rowcount} loans: '{old_value}' -> '{new_value}'")

            connection.commit()

        finally:
            cursor.close()
            connection.close()

        total_leads = sum(results["leads"].values())
        total_loans = sum(results["loans"].values())

        logger.info(f"Migration completed: {total_leads} leads, {total_loans} loans normalized")

        return {
            "success": True,
            "message": f"Normalized {total_leads} leads and {total_loans} loans",
            "details": results
        }

    except Exception as e:
        logger.error(f"Stage enum normalization failed: {e}")
        return {
            "success": False,
            "message": f"Migration failed: {str(e)}",
            "error": str(e)
        }


@app.post("/api/v1/migrations/create-financial-intelligence-tables", response_model=None)
async def create_financial_intelligence_tables_migration(
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    """
    Migration: Create financial intelligence tables.

    Creates all tables required for the Financial Intelligence module:
    - loan_sales: Individual loan sales to secondary market
    - hedge_positions: Hedge positions for rate risk management
    - secondary_metrics: Daily/monthly secondary marketing metrics
    - msr_portfolio: MSR portfolio valuation and tracking
    - warehouse_lines: Warehouse line configurations
    - warehouse_usage: Daily warehouse line usage metrics
    - product_profitability: Profitability by loan product type
    - cash_positions: Daily cash position tracking
    - cash_forecasts: Cash flow forecasting
    - burn_rates: Monthly burn rate tracking
    - competitor_rates: Competitor rate tracking
    - lost_deals: Deals lost to competitors
    - capital_requirements: Capital adequacy tracking
    - compliance_risks: Compliance and regulatory risks
    """
    try:
        logger.info(f"Running migration: create financial intelligence tables (user: {current_user.id})")

        # Import the models to ensure they're registered with Base.metadata
        from models.financial_intelligence import (
            LoanSale, HedgePosition, SecondaryMetrics, MSRPortfolio,
            WarehouseLine, WarehouseUsage, ProductProfitability,
            CashPosition, CashForecast, BurnRate, CompetitorRate,
            LostDeal, CapitalRequirement, ComplianceRisk
        )

        tables_to_create = [
            LoanSale.__table__,
            HedgePosition.__table__,
            SecondaryMetrics.__table__,
            MSRPortfolio.__table__,
            WarehouseLine.__table__,
            WarehouseUsage.__table__,
            ProductProfitability.__table__,
            CashPosition.__table__,
            CashForecast.__table__,
            BurnRate.__table__,
            CompetitorRate.__table__,
            LostDeal.__table__,
            CapitalRequirement.__table__,
            ComplianceRisk.__table__,
        ]

        created_tables = []
        existing_tables = []

        for table in tables_to_create:
            try:
                # checkfirst=True means it won't error if table exists
                table.create(bind=engine, checkfirst=True)
                # Check if table was newly created by seeing if it exists now
                if engine.dialect.has_table(engine.connect(), table.name):
                    created_tables.append(table.name)
            except Exception as table_error:
                logger.warning(f"Table {table.name} may already exist: {table_error}")
                existing_tables.append(table.name)

        logger.info(f"Financial intelligence tables migration completed. Created: {len(created_tables)}")

        return {
            "success": True,
            "message": f"Financial intelligence tables migration completed",
            "created_tables": created_tables,
            "tables_checked": [t.name for t in tables_to_create]
        }

    except Exception as e:
        logger.error(f"Financial intelligence tables migration failed: {e}")
        import traceback
        return {
            "success": False,
            "message": f"Migration failed: {str(e)}",
            "error": str(e),
            "traceback": traceback.format_exc()
        }


@app.post("/api/v1/migrations/create-beta-tables", response_model=None)
async def create_beta_tables_migration(
    current_user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    """
    Migration: Create beta program tables.

    Creates tables required for the beta program:
    - beta_applications: Beta program application submissions
    - analytics_events: User behavior event tracking
    """
    try:
        logger.info(f"Running migration: create beta tables (user: {current_user.id})")

        # Create beta_applications table
        db.execute(text("""
            CREATE TABLE IF NOT EXISTS beta_applications (
                id SERIAL PRIMARY KEY,
                company_name VARCHAR(255) NOT NULL,
                contact_name VARCHAR(255) NOT NULL,
                email VARCHAR(255) NOT NULL,
                phone VARCHAR(50),
                team_size VARCHAR(50),
                current_crm VARCHAR(255),
                monthly_loans VARCHAR(50),
                pain_points TEXT,
                use_cases TEXT,
                referral_source VARCHAR(100),
                status VARCHAR(50) DEFAULT 'pending',
                notes TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                contacted_at TIMESTAMP,
                activated_at TIMESTAMP
            )
        """))

        # Create index on email
        try:
            db.execute(text("CREATE INDEX IF NOT EXISTS idx_beta_applications_email ON beta_applications(email)"))
        except Exception:
            pass  # Index may already exist

        # Create analytics_events table
        db.execute(text("""
            CREATE TABLE IF NOT EXISTS analytics_events (
                id SERIAL PRIMARY KEY,
                event_name VARCHAR(255) NOT NULL,
                event_category VARCHAR(100),
                user_id INTEGER,
                properties JSONB DEFAULT '{}',
                session_id VARCHAR(100),
                timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                page_url TEXT,
                referrer TEXT,
                user_agent TEXT
            )
        """))

        # Create indexes for analytics_events
        try:
            db.execute(text("CREATE INDEX IF NOT EXISTS idx_analytics_events_name ON analytics_events(event_name)"))
            db.execute(text("CREATE INDEX IF NOT EXISTS idx_analytics_events_category ON analytics_events(event_category)"))
            db.execute(text("CREATE INDEX IF NOT EXISTS idx_analytics_events_user ON analytics_events(user_id)"))
            db.execute(text("CREATE INDEX IF NOT EXISTS idx_analytics_events_timestamp ON analytics_events(timestamp)"))
        except Exception:
            pass  # Indexes may already exist

        db.commit()

        logger.info("Beta tables migration completed successfully")

        return {
            "success": True,
            "message": "Beta program tables created successfully",
            "tables_created": ["beta_applications", "analytics_events"]
        }

    except Exception as e:
        logger.error(f"Beta tables migration failed: {e}")
        db.rollback()
        import traceback
        return {
            "success": False,
            "message": f"Migration failed: {str(e)}",
            "error": str(e),
            "traceback": traceback.format_exc()
        }


